import{_ as t,o as a,c as n,ag as r}from"./chunks/framework.em2JOrjF.js";const p=JSON.parse('{"title":"Managing a Retainer","description":"","frontmatter":{},"headers":[],"relativePath":"workflows/retainer-management.md","filePath":"workflows/retainer-management.md"}'),o={name:"workflows/retainer-management.md"};function i(s,e,l,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="managing-a-retainer" tabindex="-1">Managing a Retainer <a class="header-anchor" href="#managing-a-retainer" aria-label="Permalink to &quot;Managing a Retainer&quot;">​</a></h1><p>The monthly cycle for keeping a retainer healthy — from setup to end-of-month review.</p><hr><h2 id="what-makes-retainers-different" tabindex="-1">What makes retainers different <a class="header-anchor" href="#what-makes-retainers-different" aria-label="Permalink to &quot;What makes retainers different&quot;">​</a></h2><p>Retainers are not about hitting a project budget. They&#39;re about <strong>pacing</strong>: delivering the contracted hours within the month, neither over nor under. The client pays for a set number of hours per month. Under-delivering means they paid for value they didn&#39;t receive.</p><p>VERA tracks both directions with the same urgency.</p><hr><h2 id="initial-setup" tabindex="-1">Initial setup <a class="header-anchor" href="#initial-setup" aria-label="Permalink to &quot;Initial setup&quot;">​</a></h2><ol><li><p><strong>Create the project</strong>: <code>&quot;Create project Nike Monthly as Retainer with 480 hours per year&quot;</code></p><ul><li>480 h/yr = 40 h/month — VERA divides automatically</li></ul></li><li><p><strong>Set billing rate</strong> (Owner): set in <code>22. Projects Master</code> directly</p></li><li><p><strong>Assign PM</strong>: <code>&quot;Assign @alice as PM for Nike Monthly&quot;</code></p></li><li><p><strong>Create envelopes</strong>: The PM distributes hours across the team</p><ul><li>With 40 h/month across 4 team members: ~10 h/month each</li><li>Envelopes on a retainer represent the plan; they are project-lifetime, not month-specific</li></ul></li></ol><hr><h2 id="monthly-check-in" tabindex="-1">Monthly check-in <a class="header-anchor" href="#monthly-check-in" aria-label="Permalink to &quot;Monthly check-in&quot;">​</a></h2><p>Ask at any time:</p><blockquote><p>&quot;How is Nike Monthly tracking this month?&quot;</p></blockquote><p>VERA calls <code>get_project_info</code> (verifying it&#39;s a Retainer) then <code>get_retainer_status</code> and returns:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Nike Monthly — March Status</span></span>
<span class="line"><span>Hours logged: 18h of 40h (45%)</span></span>
<span class="line"><span>Days elapsed: 15 of 31</span></span>
<span class="line"><span>Pace: 1.2 h/day → projected 37h by month end</span></span>
<span class="line"><span>Forecast with allocations: 38h (95% utilisation)</span></span>
<span class="line"><span>Status: ✅ On track</span></span></code></pre></div><hr><h2 id="reading-the-status" tabindex="-1">Reading the status <a class="header-anchor" href="#reading-the-status" aria-label="Permalink to &quot;Reading the status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>What it means</th><th>What to do</th></tr></thead><tbody><tr><td>🚨 Critical overpace (&gt;150%)</td><td>Burning 3× budget</td><td>Pause non-urgent work, review scope</td></tr><tr><td>⚠️ Warning overpace (110–150%)</td><td>Trending 20–50% over</td><td>Review task breakdown, alert client if needed</td></tr><tr><td>✅ On track (90–110%)</td><td>Right on target</td><td>Nothing needed</td></tr><tr><td>⚠️ Warning underpace (50–90%)</td><td>Using less than planned</td><td>Reach out to client about additional work</td></tr><tr><td>🚨 Critical underpace (&lt;50%)</td><td>Major value unused</td><td>Immediate outreach — client paid for work not delivered</td></tr></tbody></table><hr><h2 id="envelope-aware-forecasting" tabindex="-1">Envelope-aware forecasting <a class="header-anchor" href="#envelope-aware-forecasting" aria-label="Permalink to &quot;Envelope-aware forecasting&quot;">​</a></h2><p>Two forecast methods are shown:</p><p><strong>Pace-based</strong>: projects forward based on how fast hours have been accumulating. Good if no envelopes are maintained.</p><p><strong>Envelope-aware</strong> (better): <code>hours_logged + allocated_remaining</code>. If the team has 12 hours remaining in their envelopes, this shows you the full picture — not just historical pace.</p><p>Always prefer the envelope-aware forecast when Managers actively maintain envelopes.</p><hr><h2 id="morning-summary" tabindex="-1">Morning summary <a class="header-anchor" href="#morning-summary" aria-label="Permalink to &quot;Morning summary&quot;">​</a></h2><p>VERA automatically includes retainer status in the morning summary for Managers and Owners. Critical and warning items appear without needing to ask. The morning summary shows:</p><ul><li>Hours logged vs. monthly budget</li><li>Status emoji</li><li>Projected end-of-month total</li><li>Alert for overpace/underpace</li></ul><hr><h2 id="end-of-month-review" tabindex="-1">End-of-month review <a class="header-anchor" href="#end-of-month-review" aria-label="Permalink to &quot;End-of-month review&quot;">​</a></h2><blockquote><p>&quot;Give me the February report&quot;</p></blockquote><p><code>generate_monthly_report</code> provides a portfolio view showing all retainers with their utilisation and status. For retainers that underspent, it shows the unused dollar value — the value left on the table.</p><hr><h2 id="multiple-retainers" tabindex="-1">Multiple retainers <a class="header-anchor" href="#multiple-retainers" aria-label="Permalink to &quot;Multiple retainers&quot;">​</a></h2><blockquote><p>&quot;Show me all my retainers&quot;</p></blockquote><p><code>get_pm_retainer_summary</code> gives a rolled-up view of all retainer projects assigned to the PM — status, pace, and utilisation for each. Useful for a quick portfolio scan.</p><hr><h2 id="common-situations" tabindex="-1">Common situations <a class="header-anchor" href="#common-situations" aria-label="Permalink to &quot;Common situations&quot;">​</a></h2><p><strong>Overpacing in week 1:</strong> The team is moving fast. Call <code>get_retainer_status</code> to confirm. If the forecast exceeds budget, pause non-urgent work. Check if any tasks have their own budgets that can act as sub-gates.</p><p><strong>Underpacing at mid-month:</strong> The team hasn&#39;t logged enough. This could be under-reporting (team forgot to log) or genuine under-delivery. Either way, address it. VERA shows the unused dollar value as motivation: &quot;You&#39;re leaving $X on the table.&quot;</p><p><strong>Client adds scope:</strong> If the scope grows beyond what can be delivered within the monthly budget, surface this to the client. For permanent scope increases, update the <code>hours_budget</code> to reflect the new annual total.</p>`,41)])])}const g=t(o,[["render",i]]);export{p as __pageData,g as default};
